import { describe, expect, it } from "vitest";
import { detectScopeCreep, keywords, splitIdent } from "../src/domain/scope-creep.js";
import type { BlastRadius, ChangeSet, ChangedSymbol, IntentModel } from "../src/domain/model.js";

const emptyRadius: BlastRadius = {
  origin: [],
  nodes: [],
  originEdges: [],
  sectionTotals: { callers: 0, callees: 0, type_consumers: 0, data_flows: 0, co_changes: 0, siblings: 0 },
};
const intent = (t: string): IntentModel => ({ source: "commit-message", text: t, keywords: keywords(t) });
const changed = (qn: string, deps: number, over: Partial<ChangedSymbol> = {}): ChangedSymbol => ({
  ref: { name: qn.split(".").pop()!, qualifiedName: qn, kind: "method", file: `src/${qn.split(".")[0]!.toLowerCase()}.ts`, line: 1, external: false },
  changeType: "body_changed",
  dependentsCount: deps,
  oldSignature: undefined,
  newSignature: undefined,
  ...over,
});
const cs = (symbols: ChangedSymbol[]): ChangeSet => ({ base: "a", head: "b", checkpoint: undefined, symbols, changedFiles: [] });

describe("splitIdent / keywords", () => {
  it("splits camelCase and paths", () => {
    expect(splitIdent("RedirectService.handleRequest")).toEqual(["redirect", "service", "handle", "request"]);
  });
  it("keeps meaningful terms, drops stopwords", () => {
    const k = keywords("Add rate limiting to the redirect endpoint");
    expect(k).toContain("rate");
    expect(k).toContain("limit");
    expect(k).toContain("redirect");
    expect(k).not.toContain("add");
    expect(k).not.toContain("the");
  });
});

describe("detectScopeCreep", () => {
  it("stays silent without an intent for a narrow change", () => {
    // no intent → no keyword signal; deps 3 < wide threshold → nothing to flag
    expect(detectScopeCreep(cs([changed("Db.query", 3)]), null, emptyRadius)).toEqual([]);
  });
  it("flags an unrelated change with dependents", () => {
    const f = detectScopeCreep(
      cs([changed("Db.query", 9, { changeType: "signature_changed" })]),
      intent("rate limit the redirect endpoint"),
      emptyRadius,
    );
    expect(f).toHaveLength(1);
    expect(f[0]?.symbol.qualifiedName).toBe("Db.query");
    expect(f[0]?.reason).toMatch(/no vocabulary overlap/);
  });
  it("does not flag a change that matches the intent", () => {
    const f = detectScopeCreep(
      cs([changed("RateLimiter.take", 5)]),
      intent("rate limit the redirect endpoint"),
      emptyRadius,
    );
    expect(f).toEqual([]);
  });
  it("flags a wide-reaching change regardless of intent", () => {
    const f = detectScopeCreep(cs([changed("Config.load", 20)]), null, emptyRadius);
    expect(f).toHaveLength(1);
    expect(f[0]?.severity).toBe("high");
  });
  it("never flags newly added symbols", () => {
    const f = detectScopeCreep(cs([changed("New.thing", 30, { changeType: "added" })]), intent("x"), emptyRadius);
    expect(f).toEqual([]);
  });
});

func completenessLevel(failures, files, parsedFiles, symbols int) string {
	switch {
	case files == 0:
		// Genuinely empty repo/scope — nothing to parse, so "ok" (not "unsafe":
		// there is no missing coverage to warn about).
		return "ok"
	case parsedFiles*2 < files:
		// A majority of the discovered files were never parsed — likely an
		// unsupported-language or mis-scoped run; the graph is missing most of
		// the repo. Loud "unsafe" so the caller does not trust a partial graph.
		return "unsafe"
	case parsedFiles > 0 && symbols == 0:
		// Files were parsed but zero symbols came out — the graph is empty and
		// unusable even though no hard parse failure occurred.
		return "degraded"
	case failures == 0:
		return "ok"
	case failures*4 > files:
		return "unsafe"
	default:
		return "degraded"
	}
}

// dataFlowEvidenceLimit caps how many flows one DATA_FLOWS edge carries. A
// forwarding call site rarely has more than a handful; the tail is long and
// repetitive (a struct's fields interned one by one), so the cap bounds output
// on the outliers. A truncated record is tagged evidenceTruncatedWarning.
const dataFlowEvidenceLimit = 8

// evidenceTruncatedWarning marks a relation whose evidence array was cut off at
// a limit, so a consumer reading evidence to explain the edge knows the list is
// partial rather than exhaustive.
const evidenceTruncatedWarning = "EVIDENCE_TRUNCATED"

func dedupeRelations(relations []RelationRecord) []RelationRecord {
	seen := map[string]struct{}{}
	out := make([]RelationRecord, 0, len(relations))
	for _, relation := range relations {
		key := relation.FromID + "\x00" + relation.ToID + "\x00" + relation.Type
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, relation)

type EntityChange struct {
	Type            string  `json:"type"`
	Kind            string  `json:"kind"`
	Name            string  `json:"name"`
	OldName         string  `json:"old_name,omitempty"`
	NewName         string  `json:"new_name,omitempty"`
	OldSignature    string  `json:"old_signature,omitempty"`
	NewSignature    string  `json:"new_signature,omitempty"`
	OldPath         string  `json:"old_path,omitempty"`
	NewPath         string  `json:"new_path,omitempty"`
	BeforeStartLine int     `json:"before_start_line,omitempty"`
	AfterStartLine  int     `json:"after_start_line,omitempty"`
	DependentsCount int     `json:"dependents_count"`
	Similarity      float64 `json:"similarity,omitempty"`
	// Reconciliation carries explicit identity-continuity metadata when a
	// delete+add pair was reconciled to a single change: RENAMED (same file),
	// MOVED (across files), or RECONCILED_FROM. Empty for ordinary changes.
	Reconciliation string `json:"reconciliation,omitempty"`
}

type FileChange struct {
	Path     string         `json:"path"`
	OldPath  string         `json:"old_path,omitempty"`
	Status   string         `json:"status"`
	Language string         `json:"language,omitempty"`
	Changes  []EntityChange `json:"changes"`
}

type Result struct {
	Checkpoint string            `json:"checkpoint,omitempty"`
	Base       string            `json:"base"`
	Head       string            `json:"head"`
	Files      []FileChange      `json:"files"`
	Warnings   []ProviderWarning `json:"warnings,omitempty"`
	// SchemaVersion pins the shape of this Result so a copy persisted into
	// checkpoint metadata can be read back knowing which schema it was written
	// under. Populated centrally from the package SchemaVersion const at the
	// single place Result is constructed with real content
	// (AnalyzeGitRangeWithOptions) — every caller (diff, analyze, checkpoint)
	// funnels through it.
	SchemaVersion string `json:"schema_version"`
	// ProducerVersion is the entire-graph binary version that produced this
	// Result (build-time version threaded from main.go via Options.Version).
	// Optional/omitted when the caller has no version to attribute.
	ProducerVersion string `json:"producer_version,omitempty"`
}

type Parser interface {
	Parse(path, content string) ([]Entity, string)
}

func WriteText(out io.Writer, result Result) {
	writeText(out, result)
}

