  .object({
    type: z.string(),
    kind: z.string(),
    name: z.string(),
    new_name: z.string().optional(),
    old_signature: z.string().optional(),
    new_signature: z.string().optional(),
    new_path: z.string().optional(),
    before_start_line: z.number().int().optional(),
    after_start_line: z.number().int().optional(),
